 lights=UnityEngine.Object.FindObjectsOfType<Light>(true).OrderBy(x=>x.GetInstanceID()).Select(x=>new{id=x.GetInstanceID(),transform=TransformImage(x.transform),x.enabled,x.intensity,x.range,color=new{r=x.color.r,g=x.color.g,b=x.color.b,a=x.color.a},x.type}).ToArray(),
