 volumes=UnityEngine.Object.FindObjectsOfType<MonoBehaviour>(true).Where(x=>x!=null&&x.GetType().Name.IndexOf("Volume",StringComparison.OrdinalIgnoreCase)>=0).OrderBy(x=>x.GetInstanceID()).Select(x=>new{id=x.GetInstanceID(),x.enabled,transform=TransformImage(x.transform)}).ToArray()});}
 object Proxy(JObject q){if(Time.timeScale!=0)throw new Exception("Pause disposable fixture");var runtime=Runtime();string action=(string)q["mode"]??"single";if(action=="retain"){proxyRetained=runtime;return new{retained=true};}if(action=="stale"){if(ReferenceEquals(proxyRetained,null))return new{fixtureMissing=true};bool disabledNull=proxyRetained.ReadStreetProxyDoors()==null&&proxyRetained.ReadStreetProxyInventory()==null;bool refused=false;string reason="";try{proxyRetained.ReadStreetProxyDoors(true,null);}catch(InvalidOperationException e){refused=true;reason=e.Message;}proxyRetained=null;return new{disabledNull,refused,reason};}if(action=="fixture-empty"){var source=SaveCodec.Write(Sim().State);var copy=SaveCodec.Read(source).State;if(copy==null)throw new Exception("Fixture source did not decode");int removed=0;foreach(var meal in copy.Food.Residents){removed+=meal.Memory.Entries.Count;meal.Memory.Entries.Clear();}var text=SaveCodec.Write(copy);var verify=SaveCodec.Read(text);if(verify.State==null)throw new Exception("Empty fixture did not decode");File.WriteAllText(Path.Combine(Root,"fixture-active-payload.json"),source);File.WriteAllText(Path.Combine(Root,"fixture-empty-payload.json"),text);return new{detachedCopyOnly=true,removed,sourceSchema=copy.Schema,sourceSha=Digest(source),emptySha=Digest(text),activeUnchanged=source==SaveCodec.Write(Sim().State)};}var beforeGuard=runtime.InteriorGuardDiagnostics;
 if(action=="off")return new{omittedDoors=runtime.ReadStreetProxyDoors(),falseDoors=runtime.ReadStreetProxyDoors(false),omittedInventory=runtime.ReadStreetProxyInventory(),falseInventory=runtime.ReadStreetProxyInventory(false),beforeGuard,afterGuard=runtime.InteriorGuardDiagnostics};
 int n=action=="repeat"?50:1;string payload=SaveCodec.Write(Sim().State),native=JsonConvert.SerializeObject(CombinedObservers.Native()),scene=action=="cold"?"not-sampled-for-first-call":SceneProjection();var samples=new List<object>();object firstDoor=null,firstInventory=null;
 for(int i=0;i<n;i++)foreach(string kind in new[]{"doors","inventory"}){long b=Bytes();var gc=new[]{GC.CollectionCount(0),GC.CollectionCount(1),GC.CollectionCount(2)};long start=Stopwatch.GetTimestamp();object value=kind=="doors"?(object)runtime.ReadStreetProxyDoors(true,null):runtime.ReadStreetProxyInventory(true);double ms=(Stopwatch.GetTimestamp()-start)*1000.0/Stopwatch.Frequency;long after=Bytes();string text=JsonConvert.SerializeObject(value);if(i==0){if(kind=="doors")firstDoor=value;else firstInventory=value;File.WriteAllText(Path.Combine(Root,"proxy-"+kind+"-"+(string)q["id"]+".json"),text);}samples.Add(new{kind,iteration=i,frame=Time.frameCount,ms,bytes=b<0||after<0?-1:after-b,outputBytes=System.Text.Encoding.UTF8.GetByteCount(text),gcBefore=gc,gcAfter=new[]{GC.CollectionCount(0),GC.CollectionCount(1),GC.CollectionCount(2)}});}
